css:
.sl-gallery-floating-wall { padding-block: clamp(3rem, 7vw, 6rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); overflow-x: clip; }
.sl-gallery-floating-wall .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-gallery-floating-wall .sl-wall-layout { display: flex; flex-direction: column; gap: 3rem; align-items: center; }
.sl-gallery-floating-wall .sl-wall-content { flex: 1; max-width: 460px; }
.sl-gallery-floating-wall .sl-wall-content .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.85rem, 3.8vw, 2.5rem); font-weight: 800; color: var(--smartlearn-text); margin: 0 0 1.25rem; line-height: 1.2; }
.sl-gallery-floating-wall .sl-wall-content .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0 0 2rem; line-height: 1.6; }
.sl-gallery-floating-wall .sl-wall-content .sl-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 46px; padding: 0.875rem 2rem; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text) !important; text-decoration: none; border-radius: var(--smartlearn-radius, 0.5rem); font-weight: 700; transition: background-color 0.2s ease; }
.sl-gallery-floating-wall .sl-wall-content .sl-btn:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); }
.sl-gallery-floating-wall .sl-wall-content .sl-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-floating-wall .sl-wall-media { flex: 1; position: relative; width: 100%; max-width: 600px; min-height: 420px; }
.sl-gallery-floating-wall .sl-wall-card { position: absolute; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.12); border: 4px solid var(--smartlearn-card-bg); transition: transform 0.35s ease, box-shadow 0.35s ease; background-color: var(--smartlearn-card-bg); }
.sl-gallery-floating-wall .sl-wall-card img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-floating-wall .sl-wall-main { width: 70%; height: 80%; top: 10%; inset-inline-start: 10%; z-index: 1; }
.sl-gallery-floating-wall .sl-wall-main.is-playing { z-index: 20; }
.sl-gallery-floating-wall .sl-wall-sub1 { width: 40%; height: 40%; top: 0; inset-inline-end: 0; z-index: 2; }
.sl-gallery-floating-wall .sl-wall-sub2 { width: 45%; height: 45%; bottom: 0; inset-inline-end: 10%; z-index: 3; }
.sl-gallery-floating-wall .sl-wall-badge { position: absolute; bottom: 15%; inset-inline-start: 0; z-index: 4; background-color: var(--smartlearn-card-bg); padding: 0.875rem 1.35rem; border-radius: 999px; box-shadow: 0 10px 20px rgba(0, 0, 0, 0.12); display: flex; align-items: center; gap: 0.65rem; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); }
.sl-gallery-floating-wall .sl-badge-text { font-weight: 700; color: var(--smartlearn-text); font-size: 0.875rem; }
.sl-gallery-floating-wall .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 64px; height: 64px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-floating-wall .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-floating-wall .sl-play-overlay:focus-visible, .sl-gallery-floating-wall .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-floating-wall .sl-close-video { position: absolute; top: 0.65rem; inset-inline-end: 0.65rem; z-index: 25; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
@media (min-width: 992px) { .sl-gallery-floating-wall .sl-wall-layout { flex-direction: row; justify-content: space-between; } }
@media (prefers-reduced-motion: no-preference) { .sl-gallery-floating-wall .sl-wall-main:hover { transform: translateY(-8px) scale(1.02); z-index: 10; } .sl-gallery-floating-wall .sl-wall-sub1:hover, .sl-gallery-floating-wall .sl-wall-sub2:hover { transform: translateY(-8px) scale(1.04); z-index: 10; } }
@media (prefers-reduced-motion: reduce) { .sl-gallery-floating-wall .sl-wall-card, .sl-gallery-floating-wall .sl-play-overlay, .sl-gallery-floating-wall .sl-btn { transition: none; } }
@media (max-width: 767px) {
  .sl-gallery-floating-wall .sl-wall-media { min-height: auto; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
  .sl-gallery-floating-wall .sl-wall-card { position: relative; top: auto; bottom: auto; inset-inline-start: auto; inset-inline-end: auto; width: 100%; height: 180px; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); box-shadow: none; }
  .sl-gallery-floating-wall .sl-wall-main { grid-column: 1 / -1; height: 240px; }
  .sl-gallery-floating-wall .sl-wall-badge { position: relative; bottom: auto; inset-inline-start: auto; grid-column: 1 / -1; justify-content: center; }
}

